                fj_v += __shfl_xor_sync(FJ_FULL_LANE_MASK, fj_v, fj_o, FJ_WAVEFRONT);
            }
            Kab2 = fj_v;
        }
        double Kab3;
        {
            auto fj_v = Ksh[(38 * static_cast<int32_t>(blockDim.y) + static_cast<int32_t>(threadIdx.y))];
            for (int32_t fj_o = FJ_WAVEFRONT / 2; fj_o > 0; fj_o /= 2) {
                fj_v += __shfl_xor_sync(FJ_FULL_LANE_MASK, fj_v, fj_o, FJ_WAVEFRONT);
            }
            Kab3 = fj_v;
        }
        double Kab4;
        {
            auto fj_v = Ksh[(39 * static_cast<int32_t>(blockDim.y) + static_cast<int32_t>(threadIdx.y))];
            for (int32_t fj_o = FJ_WAVEFRONT / 2; fj_o > 0; fj_o /= 2) {
                fj_v += __shfl_xor_sync(FJ_FULL_LANE_MASK, fj_v, fj_o, FJ_WAVEFRONT);
            }
            Kab4 = fj_v;
        }
        double Kab5;
        {
            auto fj_v = Ksh[(40 * static_cast<int32_t>(blockDim.y) + static_cast<int32_t>(threadIdx.y))];
            for (int32_t fj_o = FJ_WAVEFRONT / 2; fj_o > 0; fj_o /= 2) {
                fj_v += __shfl_xor_sync(FJ_FULL_LANE_MASK, fj_v, fj_o, FJ_WAVEFRONT);
            }
            Kab5 = fj_v;
        }
        // lane 0 ADDS the block into K_mn: one (A, B) per block and per launch, so no
        // two atomics of a launch meet; atomic only so that launches of several
        // classes onto one zeroed K need no ordering (#481)
        if (static_cast<int32_t>(threadIdx.y) < 1) {
            atomicAdd(&K[((ka + 0) * n_ao + (kb + 0))], Kab0);
            atomicAdd(&K[((ka + 1) * n_ao + (kb + 0))], Kab1);
            atomicAdd(&K[((ka + 2) * n_ao + (kb + 0))], Kab2);
            atomicAdd(&K[((ka + 3) * n_ao + (kb + 0))], Kab3);
            atomicAdd(&K[((ka + 4) * n_ao + (kb + 0))], Kab4);
            atomicAdd(&K[((ka + 5) * n_ao + (kb + 0))], Kab5);
        }
    }
}
